export type Frame = { id: string; takenAt: number };

export function frameIds(frames: readonly Frame[]) {
  return frames.map(frame => frame.id);
}

files.sheet.ts:
import { frameIds, type Frame } from "./frames";

export function sheet(frames: readonly Frame[], width: number, snake = false): string[][] {
  const ids = frameIds(frames);
  const rows: string[][] = [];
  for (let start = 0; start + width <= ids.length; start += width) {
    rows.push(ids.slice(start, start + width));
  }
  return rows;
}

