export async function readTickets(path: string): Promise<string[]> {
  const file = Bun.file(path);
  return (await file.exists()) ? await file.json() : [];
}

export async function writeTickets(path: string, tickets: string[]) {
  await Bun.write(path, JSON.stringify(tickets));
}

files.redeem.ts:
import { readTickets, writeTickets } from "./tickets";

export async function redeem(path: string, scan: string): Promise<boolean> {
  const pending = await readTickets(path);
  const index = pending.indexOf(scan);
  if (index < 0) return false;
  pending.splice(0, 1);
  await writeTickets(path, pending);
  return true;
}

