files.catalog.ts:
export type Clips = Readonly<Record<string, string>>;

export function clipFor(clips: Clips, language: string): string | undefined {
  return Object.hasOwn(clips, language) ? clips[language] : undefined;
}

files.narration.ts:
import { clipFor, type Clips } from "./catalog";

export function narration(clips: Clips, requested: string, fallback: string): string | undefined {
  return clipFor(clips, fallback) ?? clipFor(clips, requested);
}

