let tag = requested;
while (true) {
  const clip = clipFor(clips, tag);
  if (clip !== undefined) return clip;
  const cut = tag.lastIndexOf("-");
  if (cut < 0) return clipFor(clips, fallback);
  tag = tag.slice(0, cut);
}

